127	  static async getMetadataKeysFromEval(
128	    evalId: string,
129	    comparisonEvalIds: string[] = [],
130	  ): Promise<string[]> {
131	    interface MetadataKeyResult {
132	      key: string;
133	    }
134	
135	    const db = getDb();
136	    try {
137	      // Combine primary eval ID with comparison eval IDs
138	      const allEvalIds = [evalId, ...comparisonEvalIds];
139	
140	      // Use json_valid() to filter out malformed JSON and add LIMIT for DoS protection
141	      const query = sql`
142	        SELECT DISTINCT j.key FROM (
143	          SELECT metadata FROM eval_results
144	          WHERE eval_id IN (${sql.join(allEvalIds, sql`, `)})
145	            AND metadata IS NOT NULL
146	            AND metadata != '{}'
147	            AND json_valid(metadata)
148	          LIMIT 10000
149	        ) t, json_each(t.metadata) j
150	        ORDER BY j.key
151	        LIMIT 1000
152	      `;
153	      const results: MetadataKeyResult[] = await db.all(query);
154	      return results.map((r) => r.key);
155	    } catch (error) {
156	      // Log error but return empty array to prevent breaking the UI
157	      logger.error(
158	        `Error fetching metadata keys for eval ${evalId} and comparisons [${comparisonEvalIds.join(', ')}]: ${error}`,
159	      );
160	      return [];
161	    }
162	  }
163	}
