37	function computeAvailableMetrics(table: EvaluateTable | null): string[] {
38	  if (!table || !table.head?.prompts) {
39	    return [];
40	  }
41	
42	  const metrics = new Set<string>();
43	  table.head.prompts.forEach((prompt) => {
44	    if (prompt.metrics?.namedScores) {
45	      Object.keys(prompt.metrics.namedScores).forEach((metric) => {
46	        // Exclude policy metrics as they are handled by the separate policy filter
47	        if (!isPolicyMetric(metric)) {
48	          metrics.add(metric);
49	        }
50	      });
51	    }
52	  });
53	
54	  return Array.from(metrics).sort();
55	}
