105	  const filteredCount = Number(countResult[0]?.count ?? 0);
106	  logger.debug(`Optimized count query took ${Date.now() - countStart}ms`);
107	
108	  // Get test indices
109	  const idxStart = Date.now();
110	  const idxQuery = sql`
111	    SELECT DISTINCT test_idx 
112	    FROM ${evalResultsTable} 
113	    WHERE ${whereClause}
114	    ORDER BY test_idx 
115	    LIMIT ${limit} 
116	    OFFSET ${offset}
117	  `;
