 * Determines whether a filter is "applied" i.e. it will meaningfully constrain the results.
 *
 * - Metadata filters with the `exists` operator are applied once a field is selected (no value needed).
 * - Other metadata filters require both a field and a value.
 * - All other filter types require a value.
 */
function isFilterApplied(filter: {
  type: ResultsFilterType;
  operator: ResultsFilterOperator;
  value: string;
  field?: string;
}): boolean {
  if (filter.type === 'metadata') {
    if (filter.operator === 'exists') {
      return Boolean(filter.field);
    }
    return Boolean(filter.value && filter.field);
  }
